export function admit(snapshot, expected) {
  if (!snapshot || snapshot.run_id !== expected.runId || snapshot.attempt !== expected.attempt) return false;
  if (!Array.isArray(snapshot.jobs) || snapshot.jobs.length === 0) return false;
  return snapshot.jobs.every(job => Array.isArray(job.steps) && job.steps.length > 0 && job.steps.every(step => {
    if (step.status === 'completed') return ['success', 'skipped'].includes(step.conclusion);
    return ["queued", "running"].includes(step.status) && step.conclusion === null;
  }));
}

