import test from 'node:test';
import assert from 'node:assert/strict';
import { runPhase } from '../src/runner.mjs';
const expected = { runId: 'r-382', attempt: 3 };
const make = (status, conclusion) => ({ run_id: 'r-382', attempt: 3, jobs: [{ steps: [{ status, conclusion }] }] });
async function check(body, admitted) { let calls = 0; const result = await runPhase(async () => body, expected, async () => { calls++; }); assert.equal(result.admitted, admitted); assert.equal(calls, admitted ? 1 : 0); }
test('queued sequence', async () => check(make('queued', null), true));
test('running sequence', async () => check(make('running', null), true));
test('finished sequence', async () => check(make('completed', 'success'), true));
test('skipped sequence', async () => check(make('completed', 'skipped'), true));
test('failed', async () => check(make('completed', "failure"), false));
test('cancelled', async () => check(make('completed', "cancelled"), false));
test('terminal without conclusion', async () => check(make('completed', null), false));
test('unfinished with conclusion', async () => check(make('running', "success"), false));
test('unknown state', async () => check(make('unknown', null), false));
test('run binding', async () => { const body = make('queued', null); body.run_id = 'r-383'; await check(body, false); });
test('attempt binding', async () => { const body = make('queued', null); body.attempt = 2; await check(body, false); });
test('empty inventory', async () => check({ run_id: 'r-382', attempt: 3, jobs: [] }, false));

